{
  "findings": [
    {
      "check_id": "CKV_AZURE_113",
      "title": "MSSQL Server administrator login password is hardcoded",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "CRITICAL",
      "explanation": "The administrator login password for the MSSQL Server is hardcoded in the Terraform configuration, posing a significant security risk if the code is exposed or accessed by unauthorized parties."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server\" \"changeme_simple_mssql_server\" {\n  name                = \"changeme-simple-mssql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  version = \"12.0\"\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = sensitive(var.mssql_server_admin_password)\n}",
  "fix_summary": "Replaced the hardcoded administrator login password with a reference to a sensitive Terraform variable 'mssql_server_admin_password' to secure the password."
}
